CREATE INDEX IF NOT EXISTS idx_referral_customer ON public.user_referral_codes USING btree (customer_id);
CREATE INDEX IF NOT EXISTS idx_referral_referred_by ON public.user_referral_codes USING btree (referred_by);
ALTER TABLE ONLY public.affiliate_referrals
