CREATE INDEX IF NOT EXISTS idx_trending_dishes_last_order_at ON public.trending_dishes USING btree (last_order_at);
CREATE INDEX IF NOT EXISTS idx_trending_dishes_quantity_sold ON public.trending_dishes USING btree (quantity_sold DESC);
CREATE INDEX IF NOT EXISTS idx_trending_dishes_restaurant ON public.trending_dishes USING btree (restaurant_id);

-- ---- from notification ----
CREATE TABLE IF NOT EXISTS public.notifications (
    id bigint NOT NULL,
    channel character varying(20) NOT NULL,
    recipient character varying(255) NOT NULL,
    template character varying(100),
    subject character varying(255),
    body text,
    status character varying(20) NOT NULL,
    provider_ref character varying(100),
    error character varying(1000),
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL
);
ALTER TABLE public.notifications ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.notifications_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
ALTER TABLE ONLY public.notifications
    ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);
CREATE INDEX IF NOT EXISTS idx_notifications_channel_status ON public.notifications USING btree (channel, status);
CREATE INDEX IF NOT EXISTS idx_notifications_recipient ON public.notifications USING btree (recipient, created_at);
